-- PostgreSQL 18 EXPLAIN VERBOSE target lists (show_plan_tlist): each node
-- prints the expressions it returns, columns qualified when the range table
-- holds more than one relation. A scan under a node that accepts any
-- columns returns its relation's physical columns (use_physical_tlist), one
-- under a Sort, Hash or Materialize only those needed; an upper node prints
-- an expression its input computed in parentheses. Append prints none.
CREATE TABLE t539 (id int PRIMARY KEY, x int, s text);
CREATE TABLE u539 (id int, aid int, y int);
INSERT INTO t539 SELECT g, g % 7, 's' || g FROM generate_series(1, 50) g;
INSERT INTO u539 SELECT g, g % 50 + 1, g FROM generate_series(1, 100) g;
ANALYZE t539;
ANALYZE u539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT * FROM t539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x + 1, upper(s) FROM t539 WHERE id > 3;
EXPLAIN (VERBOSE, COSTS OFF) SELECT 1 FROM t539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT t539, s FROM t539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x + 1 FROM t539 ORDER BY 1;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x FROM t539 ORDER BY s;
EXPLAIN (VERBOSE, COSTS OFF) SELECT * FROM t539 ORDER BY s LIMIT 3;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x FROM t539 WHERE s > 'a' LIMIT 2;
EXPLAIN (VERBOSE, COSTS OFF) SELECT count(*) FROM t539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x, count(*), sum(id) FROM t539 GROUP BY x;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x + 1, count(*) FROM t539 GROUP BY x + 1;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x, count(*) FROM t539 GROUP BY x ORDER BY 2;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x, count(*) FROM t539 GROUP BY x HAVING sum(id) > 3;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x * 2, count(*) + 1 FROM t539 GROUP BY x ORDER BY count(*);
EXPLAIN (VERBOSE, COSTS OFF) SELECT max(x), min(s) FROM t539 HAVING count(*) > 0;
EXPLAIN (VERBOSE, COSTS OFF) SELECT DISTINCT x FROM t539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT * FROM t539 FOR UPDATE;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x FROM t539 LIMIT 2 FOR UPDATE;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x, row_number() OVER (ORDER BY id) FROM t539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x, sum(x) OVER (PARTITION BY s) FROM t539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x, row_number() OVER (ORDER BY id), rank() OVER (PARTITION BY x ORDER BY id) FROM t539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x, sum(id) OVER w FROM t539 WINDOW w AS (ORDER BY x);
EXPLAIN (VERBOSE, COSTS OFF) SELECT generate_series(1, x) FROM t539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT 1 + 2, 'a'::text;
EXPLAIN (VERBOSE, COSTS OFF) SELECT count(*);
EXPLAIN (VERBOSE, COSTS OFF) SELECT x FROM t539 UNION ALL SELECT y FROM u539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT x FROM t539 UNION SELECT y FROM u539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT * FROM (SELECT x, s FROM t539 ORDER BY s LIMIT 5) q WHERE x > 1;
EXPLAIN (VERBOSE, COSTS OFF) SELECT * FROM (SELECT x, count(*) c FROM t539 GROUP BY x) q WHERE c > 1;
EXPLAIN (VERBOSE, COSTS OFF) WITH c AS MATERIALIZED (SELECT id, x FROM t539) SELECT x FROM c WHERE id > 2;
EXPLAIN (VERBOSE, COSTS OFF) WITH c AS MATERIALIZED (SELECT id, x FROM t539) SELECT * FROM c a, c b WHERE a.id = b.id;
EXPLAIN (VERBOSE, COSTS OFF) SELECT s, (SELECT max(y) FROM u539 WHERE u539.aid = t539.id) FROM t539;
EXPLAIN (VERBOSE, COSTS OFF) SELECT s FROM t539 WHERE id = (SELECT max(aid) FROM u539) ORDER BY x;
EXPLAIN (VERBOSE, COSTS OFF) SELECT * FROM generate_series(1, 3) g;
EXPLAIN (VERBOSE, COSTS OFF) SELECT g + 1 FROM generate_series(1, 3) g WHERE g > 1;
EXPLAIN (VERBOSE, COSTS OFF) SELECT * FROM (VALUES (1, 'a'), (2, 'b')) v(p, q) ORDER BY q;
EXPLAIN (VERBOSE, COSTS OFF) UPDATE t539 SET s = s || 'x', x = x + 1 WHERE x = 3;
EXPLAIN (VERBOSE, COSTS OFF) DELETE FROM t539 WHERE x = 3 RETURNING id, s;
EXPLAIN (VERBOSE, COSTS OFF) DELETE FROM t539 WHERE x = 4 RETURNING *;
EXPLAIN (VERBOSE, COSTS OFF) INSERT INTO u539 SELECT id, id, x FROM t539;
EXPLAIN (VERBOSE, COSTS OFF, FORMAT JSON) SELECT x, count(*) FROM t539 GROUP BY x ORDER BY 2;
